#if UNITY_EDITOR
using System.Collections.Generic;using System.Linq;using HabitatShift.Core;using UnityEngine;namespace HabitatShift.LevelLabR10 { public static class R10Dependency { public static List<R10Edge> Build(int count){var r=new List<R10Edge>();for(var i=1;i<count;i++)r.Add(new R10Edge{from="H"+i,to="H"+(i+1),kind=i%2==0?"POCKET_OPENS":"MOVE_OPENS"});return r;} public static bool EdgeIsRealized(R10Edge edge,LevelDto level){var from=level.habitats.FirstOrDefault(h=>h.id==edge.from);var to=level.habitats.FirstOrDefault(h=>h.id==edge.to);if(from==null||to==null)return false;var top=R10Topology.Analyze(level);if(edge.kind=="MOVE_OPENS"||edge.kind=="POCKET_OPENS")return top.chokes.Any(c=>from.shape.Any(q=>from.anchor.x+q.x==c.x&&from.anchor.y+q.y==c.y))||Vector2Int.Distance(new Vector2Int(from.anchor.x,from.anchor.y),new Vector2Int(to.anchor.x,to.anchor.y))<=3; if(edge.kind=="CROSS_REGION")return (level.targets??new TargetDto[0]).Any(t=>t.color==to.color&&Vector2.Distance(new Vector2(t.position.x,t.position.y),new Vector2(to.anchor.x,to.anchor.y))>2);return true;} public static bool AllRealized(R10Project p){return p.dependencyGraph.All(e=>EdgeIsRealized(e,p.level));} } }
#endif